const API = '/api';
const nav = [['⌘','Studio chat'],['⌂','Dashboard'],['✦','Create'],['◈','Production plan'],['▤','Storyboard'],['▥','Timeline'],['▱','Assets'],['▧','Templates'],['◫','Formats'],['⟳','Automations'],['◇','MCP tools'],['◷','Jobs'],['✓','Export'],['◎','Catalog'],['⚙','Settings']];
const store = { token:'', state:{projects:[],assets:[],jobs:[],capabilities:[],formatCatalogue:{formats:[],platforms:[],variantCount:0,presets:{}}}, releases:[], project:null, active:'Studio chat', workspace:'film', loading:true, openingProject:false, selectedClip:null, dirty:false, saving:false, savePromise:null, renderedContent:'', poll:null };
const $ = s => document.querySelector(s);
const esc = v => String(v ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt = n => { if (!Number.isFinite(Number(n))) return '—'; const s = Math.max(0,Number(n)); return `${String(Math.floor(s/60)).padStart(2,'0')}:${String(Math.floor(s%60)).padStart(2,'0')}`; };
const fmtBytes = n => { const x=Number(n)||0; return x<1e6?`${Math.round(x/1024)} KB`:`${(x/1e6).toFixed(1)} MB`; };
function toast(message, kind='ok'){ const el=$('#toast'); if(!el)return; el.textContent=message; el.dataset.kind=kind; el.classList.add('show'); clearTimeout(el._t); el._t=setTimeout(()=>el.classList.remove('show'),2800); }
function fail(message){ toast(message,'error'); const b=$('#errorBanner'); if(b){ b.textContent=message; b.hidden=false; } }
let sessionRecovery=null;
async function api(path, options={}) {
 const request=()=>fetch(`${API}${path}`,{...options,headers:{...(options.body instanceof FormData?{}:{'Content-Type':'application/json'}),...(store.token?{'X-Vyrelum-Token':store.token}:{}),...(options.headers||{})}});
 let res=await request();
 if(res.status===401&&path!=='/session'){
  // The server rejected this request before mutation. Renew its loopback
  // session once and retry without discarding unsaved editor state.
  sessionRecovery||=fetch(`${API}/session`).then(async r=>{if(!r.ok)throw Error('Local session unavailable');const session=await r.json();if(!session.token)throw Error('Local session unavailable');store.token=session.token;}).finally(()=>{sessionRecovery=null;});
  await sessionRecovery;res=await request();
  if(res.ok&&$('#errorBanner')?.textContent==='Session required'){$('#errorBanner').hidden=true;$('#errorBanner').textContent='';}
 }
 let data=null;try{data=await res.json();}catch{}if(!res.ok)throw new Error(data?.error||`${res.status} ${res.statusText}`);return data;
}
async function init(){
 try{store.workspace=localStorage.getItem('vyrealm:workspace')==='creator'?'creator':'film';}catch{}
 layout(loadingWorkspace());let failure='';
 try{const session=await api('/session');store.token=session.token||'';await refresh();}catch(e){failure=`Local engine unavailable: ${e.message}`;}
 store.loading=false;render();if(failure)fail(failure);store.poll=setInterval(()=>void pollState(),3500);
}
let refreshFlight=null,polling=false,lastFullRefresh=0,stateEpoch=0;
async function refresh(){
 if(refreshFlight)return refreshFlight;
 refreshFlight=(async()=>{try { const [state,releases]=await Promise.all([api('/state'),api('/releases')]); store.state={...state,projects:state.projects||[],assets:state.assets||[],jobs:state.jobs||[],capabilities:state.capabilities||[]}; store.releases=Array.isArray(releases)?releases:[];lastFullRefresh=Date.now();stateEpoch++; const id=store.project?.id||localStorage.getItem('vyrelum:selectedProject'); if(id){ const p=store.state.projects.find(x=>x.id===id); const editableFocused=['INPUT','TEXTAREA','SELECT'].includes(document.activeElement?.tagName); if(p && !store.dirty && !store.saving && JSON.stringify(p)!==JSON.stringify(store.project)){ store.project=p; if(!p.timeline?.some(c=>c.id===store.selectedClip)) store.selectedClip=p.timeline?.[0]?.id||null; } if($('#app') && !(['Create','Timeline'].includes(store.active) && editableFocused)) updateDynamic(); } else if($('#app')) updateDynamic(); } catch(e){ if($('#app') && !$('#errorBanner')?.textContent) fail(e.message); }})();
 try{return await refreshFlight;}finally{refreshFlight=null;}
}
async function pollState(){
 // Progress polling must not repeatedly probe every installed capability or
 // hash the catalogue. Keep those checks on full refresh and job boundaries.
 if(polling||refreshFlight||document.visibilityState==='hidden')return;
 if(Date.now()-lastFullRefresh>=30000)return refresh();
 polling=true;const epoch=stateEpoch;let full=false;
 try{
  const jobs=await api('/jobs');if(!Array.isArray(jobs)||epoch!==stateEpoch||refreshFlight)return;
  const previous=new Map(store.state.jobs.map(job=>[job.id,job]));
  full=jobs.length!==previous.size||jobs.some(job=>{const old=previous.get(job.id);return !old||old.status!==job.status&&!['queued','loading','running','staging','validating','cancelling'].includes(job.status);});
  store.state.jobs=jobs;
  const editing=['INPUT','TEXTAREA','SELECT'].includes(document.activeElement?.tagName);
  if($('#app')&&!(['Create','Timeline'].includes(store.active)&&editing))updateDynamic();
 }catch(e){if($('#app')&&!$('#errorBanner')?.textContent)fail(e.message);}
 finally{polling=false;}
 if(full)await refresh();
}
const activeJobStates=new Set(['queued','loading','running','staging','validating','cancelling']);
function projectJobs(p){
 // Retries update the original job. Creation order alone can select an older attempt.
 const timestamp=job=>Date.parse(job.updatedAt||job.createdAt||'')||0;
 return store.state.jobs.filter(job=>job.projectId===p.id).slice().sort((a,b)=>timestamp(b)-timestamp(a));
}
function projectDisplayStatus(p){
 const jobs=projectJobs(p),activeJob=jobs.find(job=>activeJobStates.has(job.status));
 if(activeJob){const progress=Number.isFinite(activeJob.progress)?` · ${Math.round(Math.max(0,Math.min(1,activeJob.progress))*100)}%`:'';return {label:activeJob.status.toUpperCase(),detail:`${activeJob.type||'Production'}${progress}${activeJob.stage?` · ${activeJob.stage}`:''}`,activeJob};}
 const latest=jobs[0];
 if(latest?.output?.promoted===false&&['generation-test','generation-shot'].includes(latest.type)&&['review_required','rejected','succeeded'].includes(latest.status)&&!p.operations?.some(op=>op.type==='apply_generated_shot'&&op.jobId===latest.id))return {label:latest.status==='review_required'?'REVIEW':latest.status==='rejected'?'REJECTED':'RETAINED',detail:latest.status==='review_required'?'Retained shot needs visual review':latest.status==='rejected'?'Retained shot rejected':latest.output.review?.verdict==='passed'?'Reviewed shot retained; apply it from Jobs':'Retained shot; inspect it from Jobs'};
 const output=p.latestOutput,provenance=output?.provenance||{},out=output?.videoAssetId&&store.state.assets.some(a=>a.id===output.videoAssetId);
 return {label:output?.status==='rejected'?'REJECTED':output?.status==='blocked'?'BLOCKED':provenance.generationStatus==='fallback'?'FALLBACK':provenance.generationStatus==='imported'?'IMPORTED':output?.status==='review_required'?'REVIEW':out?'RENDERED':'DRAFT',detail:output?.status==='review_required'?'visual review required':output?.status==='blocked'?'generation blocked':''};
}
function previousBlockedDetail(p){
 if(p.latestOutput?.status!=='blocked')return '';
 const output=p.latestOutput,job=store.state.jobs.find(j=>j.id===output.jobId);
 const reason=output.diagnostic?.message||output.reason||output.error||(!activeJobStates.has(job?.status)&&(job?.error||job?.stage));
 return `Previous output remains blocked${typeof reason==='string'&&reason?`: ${reason}`:'. Its diagnostic is retained in Jobs.'}`;
}
function projectCard(p){const poster=p.latestOutput?.posterAssetId?store.state.assets.find(a=>a.id===p.latestOutput.posterAssetId):null,status=projectDisplayStatus(p);return `<button class="project-card" data-open-project="${esc(p.id)}"><div class="project-art" ${poster&&p.latestOutput?.status!=='blocked'?`style="background-image:url('${esc(poster.url)}')"`:''}><span class="tag">${esc(status.label)}</span><span class="project-open">Open →</span></div><div class="project-info"><strong>${esc(p.name||'Untitled')}</strong><span>${fmt((p.timeline||[]).reduce((a,c)=>a+Number(c.duration||0),0))} · rev ${p.revision||0}${status.detail?` · ${esc(status.detail)}`:''}</span></div></button>`;}
function reviewOutputHash(provenance){
 // Legacy generated receipts bind outputHash to the native clip. The server
 // verifies and migrates those receipts before recording a delivery review.
 if(provenance?.generationStatus==='generated'&&!provenance.source)return undefined;
 return /^[a-f0-9]{64}$/.test(provenance?.outputHash||'')?provenance.outputHash:undefined;
}
function workspaceDefinition(){return store.workspace==='creator'?{label:'Creator OS',description:'Ideas, formats & publishing',primary:['Studio chat','Dashboard','Create','Assets','Formats','Templates','Automations'],secondary:'Film tools'}:{label:'Film Studio',description:'Direction, editing & finishing',primary:['Studio chat','Dashboard','Create','Production plan','Storyboard','Timeline','Export'],secondary:'Creator tools'};}
function loadingWorkspace(){return '<div class="workspace-loading" role="status" aria-live="polite"><div class="eyebrow">Opening your workspace</div><h1>Your studio is loading.</h1><p>Reading local projects and production status.</p><div class="skeleton skeleton-title"></div><div class="skeleton skeleton-stage"></div><span class="sr-only">Please wait for the local engine.</span></div>';}
function layout(content){
 const workspace=workspaceDefinition(),primary=workspace.primary.map(label=>nav.find(item=>item[1]===label)),tools=nav.filter(item=>!workspace.primary.includes(item[1])&&!['Jobs','Catalog','Settings','MCP tools'].includes(item[1]));
 document.documentElement?.classList?.remove('navigation-open');
 document.querySelector('#app').innerHTML=`<div class="shell" data-workspace="${store.workspace}"><button class="sidebar-backdrop" id="sidebarBackdrop" aria-label="Close navigation" hidden></button><aside class="sidebar" id="sidebar" aria-label="Studio navigation"><div class="brand"><span class="brand-mark" aria-hidden="true"></span>VYREALM<button class="icon-btn sidebar-close" id="closeMenuBtn" aria-label="Close navigation">×</button></div><div class="workspace-switcher" role="group" aria-label="Choose workspace"><button data-workspace="creator" aria-pressed="${store.workspace==='creator'}"><span class="workspace-glyph" aria-hidden="true">◫</span><span><strong>Creator OS</strong><small>Content & campaigns</small></span></button><button data-workspace="film" aria-pressed="${store.workspace==='film'}"><span class="workspace-glyph" aria-hidden="true">▰</span><span><strong>Film Studio</strong><small>Stories & cinema</small></span></button></div><div class="sidebar-scroll"><div class="eyebrow nav-section">${workspace.label}</div><nav aria-label="${workspace.label}">${primary.map(navItem).join('')}</nav><div class="eyebrow nav-section">${workspace.secondary}</div><nav aria-label="More creative tools">${tools.map(navItem).join('')}</nav><div class="eyebrow nav-section">Workspace</div><nav aria-label="Workspace tools">${['Catalog','Jobs','MCP tools','Settings'].map(label=>navItem(nav.find(item=>item[1]===label))).join('')}</nav></div><div class="sidebar-foot"><span class="local-status-dot" aria-hidden="true"></span><div><strong>On your machine</strong><small>Projects stay with you</small></div></div></aside><main class="main" id="mainContent"><header class="topbar"><div class="top-left"><button class="icon-btn mobile-menu" id="menuBtn" aria-label="Open navigation" aria-expanded="false" aria-controls="sidebar">☰</button><div class="crumb">${workspace.label} <span>/</span> <strong>${esc(store.active)}</strong></div></div><div class="top-actions"><label class="search-wrap"><span aria-hidden="true">⌕</span><input class="search" id="search" aria-label="Search visible projects or assets" placeholder="Search your workspace" ${store.loading?'disabled':''}/><kbd>⌕</kbd></label><span class="credit"><i></i> Local</span><button class="icon-btn" id="refreshBtn" aria-label="Refresh workspace" ${store.loading?'disabled':''}>↻</button></div></header><div id="errorBanner" class="error-banner" role="alert" hidden></div><section class="content" aria-busy="${store.loading}">${content}</section></main><nav class="mobile-bottom-nav" aria-label="Quick navigation"><button data-nav="Studio chat" ${store.active==='Studio chat'?'aria-current="page"':''}><span aria-hidden="true">⌘</span>Studio</button><button data-nav="Create" ${store.active==='Create'?'aria-current="page"':''}><span aria-hidden="true">＋</span>Create</button><button data-nav="Jobs" ${store.active==='Jobs'?'aria-current="page"':''}><span aria-hidden="true">◷</span>Jobs</button><button id="bottomMenuBtn" aria-label="Open all tools" aria-controls="sidebar" aria-expanded="false"><span aria-hidden="true">☰</span>Tools</button></nav><input type="file" id="mediaInput" accept="image/*,video/*,audio/*" hidden><input type="file" id="bundleInput" accept="application/json,.json" hidden><div class="toast" id="toast" role="status" aria-live="polite"></div></div>`;
 bindLayout();setMobileNavigation(false,{focus:false});
}
function navItem(item){return `<button class="nav-item ${store.active===item[1]?'active':''}" data-nav="${item[1]}" ${store.active===item[1]?'aria-current="page"':''}><span class="nav-icon" aria-hidden="true">${item[0]}</span>${item[1]}</button>`;}
function render(){ const content=store.active==='Studio chat'?studioChat():store.active==='Dashboard'?explore():store.active==='Create'?studio():store.active==='Production plan'?cinema():store.active==='Storyboard'?storyboard():store.active==='Timeline'?studio():store.active==='Assets'?library():store.active==='Formats'?formatLab():store.active==='Jobs'?jobs():store.active==='MCP tools'?mcpTools():store.active==='Export'?review():store.active==='Catalog'?catalog():['Templates','Automations','Settings'].includes(store.active)?productSection(store.active):generic(store.active); store.renderedContent=content; layout(content); bindPage(); }
function setMobileNavigation(open,{focus=true}={}){
 const sidebar=$('#sidebar'),backdrop=$('#sidebarBackdrop');if(!sidebar)return;const narrow=globalThis.matchMedia?.('(max-width:760px)')?.matches||false;open=Boolean(open&&narrow);sidebar.classList.toggle('open',open);sidebar.inert=narrow&&!open;if(backdrop)backdrop.hidden=!open;document.documentElement.classList.toggle('navigation-open',open);if($('#mainContent'))$('#mainContent').inert=open;if($('.mobile-bottom-nav'))$('.mobile-bottom-nav').inert=open;
 for(const id of ['#menuBtn','#bottomMenuBtn'])$(id)?.setAttribute('aria-expanded',String(open));
 if(focus)(open?$('#closeMenuBtn'):$('#menuBtn'))?.focus();
}
function bindNavigation(){document.querySelectorAll('[data-nav]').forEach(button=>button.onclick=()=>{if(store.loading)return;store.active=button.dataset.nav;setMobileNavigation(false,{focus:false});render();});}
function bindLayout(){
 bindNavigation();
 document.querySelectorAll('[data-workspace]').forEach(button=>{if(button.tagName!=='BUTTON')return;button.onclick=()=>{if(store.loading)return;store.workspace=button.dataset.workspace==='creator'?'creator':'film';try{localStorage.setItem('vyrealm:workspace',store.workspace);}catch{}setMobileNavigation(false,{focus:false});render();};});
 for(const id of ['#menuBtn','#bottomMenuBtn'])$(id)?.addEventListener('click',()=>setMobileNavigation(!$('#sidebar').classList.contains('open')));
 for(const id of ['#closeMenuBtn','#sidebarBackdrop'])$(id)?.addEventListener('click',()=>setMobileNavigation(false));
 $('#refreshBtn')?.addEventListener('click',async event=>{const button=event.currentTarget;if(button.disabled)return;button.disabled=true;button.setAttribute('aria-busy','true');try{await refresh();render();toast('Workspace refreshed');}catch(error){fail(error.message);}finally{if(button.isConnected){button.disabled=false;button.removeAttribute('aria-busy');}}});
 $('#search')?.addEventListener('input',event=>{const q=event.target.value.toLowerCase();document.querySelectorAll('.project-card,.asset-row').forEach(item=>item.hidden=!item.textContent.toLowerCase().includes(q));});
}
document.addEventListener('keydown',event=>{const sidebar=$('#sidebar');if(!sidebar?.classList.contains('open'))return;if(event.key==='Escape'){event.preventDefault();setMobileNavigation(false);return;}if(event.key==='Tab'){const controls=[...sidebar.querySelectorAll('button:not(:disabled),a[href],input:not(:disabled)')].filter(el=>el.getClientRects().length);const first=controls[0],last=controls.at(-1);if(event.shiftKey&&document.activeElement===first){event.preventDefault();last?.focus();}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first?.focus();}}});
if(typeof window!=='undefined')window.addEventListener('resize',()=>setMobileNavigation(false,{focus:false}));
function bindPage(){ bindNavigation();if(store.active==='Studio chat')bindStudioChat(); document.querySelectorAll('[data-open-project]').forEach(b=>b.onclick=async()=>{ if(store.loading||store.openingProject)return;store.openingProject=true;b.disabled=true;b.setAttribute('aria-busy','true');try{if(store.dirty&&store.project){await saveProject();if(store.dirty)throw Error('Save the current edits before opening another project.');}store.project=await api(`/projects/${b.dataset.openProject}`);store.dirty=false;store.selectedClip=store.project.timeline?.[0]?.id||null;localStorage.setItem('vyrelum:selectedProject',store.project.id);store.active=b.dataset.openView||'Create';render();}catch(e){fail(e.message);}finally{store.openingProject=false;if(b.isConnected){b.disabled=false;b.removeAttribute('aria-busy');}} }); $('#newProject')?.addEventListener('click',()=>{store.project=null;store.dirty=true;store.active='Create';render();}); $('#importBtn')?.addEventListener('click',()=>$('#bundleInput').click()); $('#uploadBtn')?.addEventListener('click',()=>$('#mediaInput').click()); $('#bundleInput')?.addEventListener('change',importBundle); $('#mediaInput')?.addEventListener('change',uploadAsset); $('#saveProject')?.addEventListener('click',saveProject); $('#saveProject2')?.addEventListener('click',saveProject); $('#renderBtn')?.addEventListener('click',()=>queueJob('render')); $('#sceneBtn')?.addEventListener('click',()=>queueJob('scene')); $('#directBtn')?.addEventListener('click',()=>queueJob('direct')); $('#produceBtn')?.addEventListener('click',()=>queueJob('produce')); $('#generateVariations')?.addEventListener('click',generateVariations); $('#exportBtn')?.addEventListener('click',exportProject); $('#prepareRelease')?.addEventListener('click',createRelease); $('#cancelBtn')?.addEventListener('click',()=>jobAction('cancel')); $('#retryBtn')?.addEventListener('click',()=>jobAction('retry')); document.querySelectorAll('[data-clip]').forEach(b=>b.onclick=()=>{store.selectedClip=b.dataset.clip;updateDynamic();}); document.querySelectorAll('[data-field]').forEach(el=>el.oninput=()=>{ if(!store.project)return; const clip=store.project.timeline?.find(c=>c.id===store.selectedClip); if(!clip)return; const key=el.dataset.field; clip[key]=key==='duration'||key==='trimStart'?Math.max(0,Number(el.value)||0):el.value; store.dirty=true; clearTimeout(store.saveTimer);store.saveTimer=setTimeout(()=>void saveProject(),1200); }); $('#soundtrackGain')?.addEventListener('input',e=>{if(!store.project?.soundtrack)return;store.project.soundtrack.gain=Math.max(0,Math.min(8,Number(e.target.value)||0));store.dirty=true;clearTimeout(store.saveTimer);store.saveTimer=setTimeout(()=>void saveProject(),1200);}); $('#soundtrackMuted')?.addEventListener('change',e=>{if(!store.project?.soundtrack)return;store.project.soundtrack.muted=Boolean(e.target.checked);store.dirty=true;clearTimeout(store.saveTimer);store.saveTimer=setTimeout(()=>void saveProject(),1200);}); $('#createProjectBtn')?.addEventListener('click',createProject); bindScene(); }
function bindScene(){const p=store.project;if(!p)return;$('#sceneObject')?.addEventListener('change',()=>{const o=p.scene?.objects?.find(x=>x.id===$('#sceneObject').value);if(o){const q=o.position||[0,0,0];document.querySelectorAll('[data-scene]').forEach((el,i)=>el.value=q[i]||0);}});document.querySelectorAll('[data-scene]').forEach(el=>el.oninput=()=>{const o=p.scene?.objects?.find(x=>x.id===$('#sceneObject')?.value)||p.scene?.objects?.[0];if(!o)return;o.position=o.position||[0,0,0];o.position[{x:0,y:1,z:2}[el.dataset.scene]]=Number(el.value)||0;store.dirty=true;clearTimeout(store.saveTimer);store.saveTimer=setTimeout(saveProject,1200);});$('[data-scene-light]')?.addEventListener('input',e=>{const l=p.scene?.lights?.[0];if(l){l.energy=Math.max(0,Number(e.target.value)||0);store.dirty=true;clearTimeout(store.saveTimer);store.saveTimer=setTimeout(saveProject,1200);}});}
function bindEvents(){ bindPage(); }
function updateDynamic(){ const content=$('.content'); if(!content)return;if(store.active==='Studio chat'){updateStudioChat();return;} const editableFocused=['INPUT','TEXTAREA','SELECT'].includes(document.activeElement?.tagName); if(['Create','Production plan','Timeline','Storyboard','Export'].includes(store.active)&&editableFocused)return; const next=store.active==='Dashboard'?explore():store.active==='Create'||store.active==='Timeline'?studio():store.active==='Jobs'?jobs():store.active==='Production plan'?cinema():store.active==='Storyboard'?storyboard():store.active==='Formats'?formatLab():store.active==='MCP tools'?mcpTools():store.active==='Catalog'?catalog():store.active==='Export'?review():['Templates','Automations','Settings'].includes(store.active)?productSection(store.active):null; if(next==null||next===store.renderedContent)return; const oldVideo=content.querySelector('video.media-preview'); const oldTime=oldVideo?.currentTime||0,wasPlaying=oldVideo&&!oldVideo.paused; content.innerHTML=next; store.renderedContent=next; bindPage(); const newVideo=content.querySelector('video.media-preview'); if(oldVideo&&newVideo&&oldVideo.getAttribute('src')===newVideo.getAttribute('src')){newVideo.replaceWith(oldVideo); try{oldVideo.currentTime=oldTime;if(wasPlaying)void oldVideo.play();}catch{}} }
async function createProject(){ const name=$('#projectName')?.value.trim()||'Untitled production', brief=$('#projectBrief')?.value.trim()||''; if(!brief){fail('Add a brief before creating the project.');return;} const profiles={1080:{width:1920,height:1080},2160:{width:3840,height:2160},720:{width:1280,height:720}}, mode=$('#projectMode')?.value||'cinematic', productTemplate=$('#productTemplate')?.value||'studio', productCamera=$('#productCamera')?.value||'dolly-in', sampleId=mode==='cinematic'?($('#cinematicSource')?.value||null):null; const resolution=$('#projectResolution')?.value||'1080', profile=mode==='product' ? profileForProduct(resolution) : (profiles[resolution]||profiles[1080]), fps=Math.max(12,Math.min(60,Number($('#projectFps')?.value)||24)); try{store.project=await api('/projects',{method:'POST',body:JSON.stringify({name,brief,mode,sampleId,productTemplate:mode==='product'?productTemplate:null,productCamera:mode==='product'?productCamera:null,durationSeconds:mode==='product'?15:sampleId==='rain-market'?15:null,settings:{...profile,fps}})});store.dirty=false;localStorage.setItem('vyrelum:selectedProject',store.project.id);toast(mode==='product'?'Product project created — import a product image':sampleId?'Cinematic test source attached':'Project created');render();}catch(e){fail(e.message);} }
async function generateVariations(){ if(!store.project)return; const button=$('#generateVariations'); if(button)button.disabled=true; try{const result=await api(`/projects/${store.project.id}/variations`,{method:'POST',body:JSON.stringify({expectedRevision:store.project.revision,count:120})});store.project=result;store.dirty=false;toast(`${Number(result.variationCount||0)} editable recipes saved`);render();}catch(e){fail(`Variation planning failed: ${e.message}`);}finally{if(button)button.disabled=false;} }
function studio(){const p=store.project; if(!p)return `<div class="hero"><div><div class="eyebrow">Create / New production</div><h1>Start with a <em>brief.</em></h1><p class="hero-copy">Describe the story, then choose a delivery profile. VYREALM keeps the production graph editable from the first frame to export.</p></div><div class="hero-note"><span class="hero-note-dot"></span>Local inference ready</div></div><div class="panel create-form"><div class="field"><label>PROJECT NAME</label><input id="projectName" placeholder="A name for this production"></div><div class="field"><label>BRIEF</label><textarea id="projectBrief" placeholder="Subject, setting, action, mood, and intended audience..."></textarea></div><div class="row profile-row"><div class="field"><label>PRODUCTION TYPE</label><select id="projectMode"><option value="cinematic">Cinematic film</option><option value="product">Product video / ad</option></select></div><div class="field"><label>PRODUCT TEMPLATE</label><select id="productTemplate"><option value="studio">Studio hero</option><option value="lifestyle">Lifestyle scene</option><option value="with-model">With model</option><option value="ugc-faceless">UGC faceless</option><option value="ugc-talking-head">UGC talking head</option><option value="ugc-silent">UGC silent</option><option value="motion-2d">2D product motion</option><option value="motion-mixed-media">Mixed media</option><option value="360-orbit">360 orbit</option><option value="unboxing">Unboxing</option><option value="demo">Product demo</option></select></div><div class="field"><label>CAMERA MOVE</label><select id="productCamera"><option value="dolly-in">Dolly in</option><option value="hero-orbit">Hero orbit</option><option value="pan-right">Pan right</option><option value="pan-left">Pan left</option><option value="crane-up">Crane up</option><option value="handheld">Handheld</option><option value="crash-zoom">Crash zoom</option><option value="static">Static hero</option></select></div></div><div class="profile-heading"><div><div class="eyebrow">Delivery profile</div><strong>Set the canvas before you direct</strong></div><span class="profile-badge">LOCAL EXPORT</span></div><div class="row profile-row"><div class="field"><label>RESOLUTION</label><select id="projectResolution"><option value="1080">Full HD · 1920 × 1080</option><option value="2160">Ultra HD · 3840 × 2160</option><option value="720">HD · 1280 × 720</option></select></div><div class="field"><label>FRAME RATE</label><select id="projectFps"><option value="24" selected>24 fps · Cinematic</option><option value="30">30 fps · Standard</option><option value="60">60 fps · Motion</option></select></div></div><div class="profile-foot"><span>Profile is stored with this project revision.</span><button class="btn primary" id="createProjectBtn">Create project <span>→</span></button></div></div>`; const clips=p.timeline||[], clip=clips.find(c=>c.id===store.selectedClip)||clips[0]; const asset=clip&&store.state.assets.find(a=>a.id===clip.assetId); const soundtrack=p.soundtrack; const settings=p.settings||{}; return `<div class="hero"><div><div class="eyebrow">Create / ${esc(p.name)}${p.mode==='product'?' · PRODUCT STUDIO':''}</div><h1>Shape a <em>world.</em></h1><p class="hero-copy">${esc(p.brief||'No brief recorded.')} <span class="revision">Revision ${p.revision}</span>${p.mode==='product'?'<span class="revision"> · '+esc(p.productTemplate||'studio')+' · '+esc(p.productCamera||'dolly-in')+(p.productAssetId?'':' · import a product image')+'</span>':''}</p></div><div class="hero-actions"><span class="output-chip">${Number(settings.width||640)} × ${Number(settings.height||360)} · ${Number(settings.fps||24)} FPS</span><button class="btn ghost" id="uploadBtn">＋ Import media</button><button class="btn" id="saveProject">Save revision</button><button class="btn" id="generateVariations">Plan 120 variants</button><button class="btn primary" id="produceBtn">Produce local film <span>→</span></button></div></div><div class="workspace"><div class="panel"><div class="panel-title"><h3>Timeline</h3><span class="eyebrow">${fmt(clips.reduce((n,c)=>n+Number(c.duration||0),0))} · ${clips.length} clips</span></div>${clips.length?`<div class="clip-list">${clips.map(c=>{const a=store.state.assets.find(x=>x.id===c.assetId);return `<button class="timeline-clip ${c.id===clip?.id?'selected':''}" data-clip="${esc(c.id)}"><span>${esc(a?.name||c.kind||'Clip')}</span><span>${fmt(c.duration)}</span></button>`}).join('')}</div><div class="timeline-editor"><div class="field"><label>DURATION (SECONDS)</label><input type="number" min="0.1" step="0.1" data-field="duration" value="${esc(clip?.duration||0)}"></div><div class="field"><label>TRIM START (SECONDS)</label><input type="number" min="0" step="0.1" data-field="trimStart" value="${esc(clip?.trimStart||0)}"></div><div class="field"><label>CAPTION</label><textarea data-field="caption" rows="3" placeholder="Caption for this shot">${esc(clip?.caption||'')}</textarea></div></div>`:`<div class="empty">Import a video or image to add the first clip.</div>`}${soundtrack?`<div class="timeline-editor soundtrack-editor"><div class="field"><label>SOUNDTRACK GAIN</label><input id="soundtrackGain" type="number" min="0" max="8" step="0.05" value="${esc(soundtrack.gain??1)}"></div><label class="checkbox"><input id="soundtrackMuted" type="checkbox" ${soundtrack.muted?'checked':''}> Mute soundtrack</label></div>`:''}<div class="panel-actions"><button class="btn" id="sceneBtn">Build 3D scene</button><button class="btn" id="directBtn">Plan only</button><button class="btn" id="renderBtn">Render edit</button><button class="btn" id="exportBtn">Export portable</button></div></div><div class="panel preview-panel"><div class="panel-title"><h3>Preview</h3><span class="tag" style="position:static">${p.latestOutput?'RENDERED':'EDITABLE'}</span></div>${preview(p,asset)}<div class="asset-strip">${store.state.assets.filter(a=>a.projectId===p.id||!a.projectId).slice(0,8).map(a=>`<button class="asset-chip" data-asset="${a.id}">${esc(a.name)}</button>`).join('')}</div></div></div>`; }
function profileForProduct(resolution){return resolution==='2160'?{width:2160,height:3840}:resolution==='720'?{width:720,height:1280}:{width:1080,height:1920};}
async function saveProject(){ if(!store.project)return false; if(store.savePromise)return store.savePromise; const p=JSON.parse(JSON.stringify(store.project)); store.saving=true; store.savePromise=(async()=>{let ok=false;try{const saved=await api(`/projects/${p.id}`,{method:'PATCH',body:JSON.stringify({expectedRevision:p.revision,name:p.name,brief:p.brief,mode:p.mode,sampleId:p.sampleId,productTemplate:p.productTemplate,productCamera:p.productCamera,productAssetId:p.productAssetId,durationSeconds:p.durationSeconds,timeline:p.timeline,scene:p.scene,settings:p.settings,soundtrack:p.soundtrack,audioTracks:p.audioTracks,narrationText:p.narrationText,transcript:p.transcript,captionsEnabled:p.captionsEnabled})}); const changed=store.project?.id===p.id&&JSON.stringify(store.project)!==JSON.stringify(p); if(changed){store.project={...store.project,revision:saved.revision,updatedAt:saved.updatedAt};store.dirty=true;}else{store.project=saved;store.dirty=false;} ok=true;toast('Saved revision '+saved.revision);updateDynamic();}catch(e){fail(`Save failed: ${e.message}`);}finally{store.saving=false;store.savePromise=null;} if(ok&&store.dirty){clearTimeout(store.saveTimer);store.saveTimer=setTimeout(()=>void saveProject(),250);} return ok;})(); return store.savePromise; }
async function uploadAsset(e){ const file=e.target.files?.[0]; if(!file)return; try{const h={'X-Filename':encodeURIComponent(file.name),'Content-Type':file.type||'application/octet-stream'};if(store.project)h['X-Project-Id']=store.project.id;const asset=await api('/assets',{method:'POST',headers:h,body:file});toast(`Imported ${file.name}`);await refresh(); if(store.project?.mode==='product' && asset.kind==='image'){store.project.productAssetId=asset.id;store.dirty=true;} if(store.project && ['video','image','audio'].includes(asset.kind)){ if(asset.kind==='audio')store.project.soundtrack={assetId:asset.id,gain:1}; else {store.project.timeline=store.project.timeline||[];store.project.timeline.push({id:crypto.randomUUID(),assetId:asset.id,kind:asset.kind,duration:Number(asset.metadata?.duration||5),trimStart:0,caption:'',color:'#8B5CF6'});}store.dirty=true;updateDynamic();} }catch(e){fail(`Import failed: ${e.message}`);}finally{e.target.value='';} }
async function importBundle(e){const file=e.target.files?.[0];if(!file)return;try{const text=await file.text();store.project=await api('/projects/import',{method:'POST',body:text});store.active='Create';store.dirty=false;localStorage.setItem('vyrelum:selectedProject',store.project.id);toast('Portable project imported');render();}catch(err){fail(`Import failed: ${err.message}`);}finally{e.target.value='';}}
async function jobAction(action){const id=$('#jobId')?.value;if(!id)return;try{const job=await api(`/jobs/${id}/${action}`,{method:'POST',body:'{}'});toast(`${action==='cancel'?'Cancellation':'Retry'} requested`);await refresh();render();}catch(e){fail(e.message);} }
async function exportProject(){if(!store.project)return;try{const blob=await api(`/projects/${store.project.id}/export`);const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([JSON.stringify(blob,null,2)],{type:'application/json'}));a.download=`${(store.project.name||'vyrelum-project').replace(/[^a-z0-9]+/gi,'-').toLowerCase()}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),500);toast('Portable project exported');}catch(e){fail(e.message);} }
async function createRelease(){if(!store.project)return;const channelId=$('#releaseChannel')?.value.trim(),title=$('#releaseTitle')?.value.trim()||store.project.name;if(!channelId||!title){fail('Channel ID and title are required before preparing a release.');return;}try{await api('/releases',{method:'POST',body:JSON.stringify({projectId:store.project.id,channelId,title,privacyStatus:$('#releasePrivacy')?.value||'private',containsSyntheticMedia:$('#releaseAi')?.checked!==false,aiRationale:'Generated or assisted media is disclosed for owner review.'})});await refresh();toast('Release package prepared locally');updateDynamic();}catch(e){fail(`Release package failed: ${e.message}`);} }
function featuredProduction(){return store.state.projects.find(p=>!p.demo&&/mahabharat|between two armies/i.test(p.name||''))||store.state.projects.find(p=>!p.demo)||null;}
function workflowRail(project){
 const clips=project?.timeline||[],hasScript=Boolean(project?.script?.trim()),hasResearch=Boolean(project?.research?.length),reviewed=project?.latestOutput?.status==='reviewed';
 const steps=[['Research','Production plan',hasResearch?'Sources saved':'Add sources'],['Script','Create',hasScript?'Script saved':'Write your brief'],['Shots','Storyboard',clips.length?String(clips.length)+' on timeline':'Sources needed'],['Edit','Timeline',clips.length?fmt(clips.reduce((n,c)=>n+Number(c.duration||0),0))+' arranged':'Build the sequence'],['Review','Export',reviewed?'Review recorded':'Review required'],['Export','Export',reviewed?'Reviewed output':'After review']];
 return '<div class="workflow-rail" aria-label="Production workflow">'+steps.map(([title,view,note],i)=>'<button class="workflow-step" '+(project?'data-open-project="'+esc(project.id)+'" data-open-view="'+view+'"':'data-nav="'+view+'"')+'><span class="workflow-index">'+String(i+1).padStart(2,'0')+'</span><strong>'+title+'</strong><small>'+esc(note)+'</small><span class="workflow-arrow" aria-hidden="true">↗</span></button>').join('')+'</div>';
}
function explore(){
 const ps=store.state.projects.filter(p=>!p.demo),featured=featuredProduction(),status=featured?projectDisplayStatus(featured):null,active=store.state.jobs.filter(j=>activeJobStates.has(j.status)).length,film=store.workspace!=='creator';
 const title=featured?featured.name.replace(/^Mahabharata\s*[·:\-]\s*/i,''):film?'Your next story':'Your next idea';
 const approved=featured?.latestOutput?.status==='reviewed',planned=Number(featured?.durationSeconds||0),clips=featured?.timeline||[];
 const projectLink=featured?'data-open-project="'+esc(featured.id)+'"':'data-nav="Create"';
 const context=featured?projectJobs(featured).slice(0,2):[];
 return '<div class="home-heading"><div><div class="eyebrow">'+(film?'Film Studio':'Creator OS')+' / Your workspace</div><h1>'+(film?'Make room for the story.':'From idea to your audience.')+'</h1></div><div class="hero-actions"><button class="btn ghost" id="importBtn">Import project</button><button class="btn primary" id="newProject">'+(film?'＋ New film':'＋ New project')+'</button></div></div><section class="production-hero" aria-label="Current production"><div class="production-copy"><div class="production-kicker"><span class="production-marker"></span>'+(approved?'Reviewed local project':'Work in progress')+'</div><h2>'+esc(title)+'</h2><p>'+(featured?esc(featured.brief||'Continue shaping this local production.'):film?'Turn an original brief into shots, an editable sequence and a reviewed film.':'Plan a story, bring your media and shape versions for your audience.')+'</p><div class="production-actions"><button class="btn primary" '+projectLink+'>'+(featured?'Continue production':'Start with a brief')+' <span aria-hidden="true">↗</span></button><button class="btn ghost" data-nav="Jobs">View production jobs</button></div><div class="production-specs">'+(featured?'<span>REV '+Number(featured.revision||0)+'</span><span>'+Number(featured.settings?.fps||24)+' FPS target</span>'+(planned?'<span>'+fmt(planned)+' planned</span>':''):'<span>Local creation</span><span>Editable projects</span>')+'</div></div><aside class="production-slate"><div class="slate-heading"><span class="eyebrow">'+(featured?'Current production status':'Your first production')+'</span><span class="slate-dot" aria-hidden="true"></span></div><div class="slate-status">'+esc(status?.label||'READY TO BEGIN')+'</div><p class="slate-detail">'+esc(status?.detail||(featured?'The project is saved. Continue through its production stages.':'Create a brief to begin. No media has been generated yet.'))+'</p><div class="slate-rule"></div><dl><div><dt>Sequence</dt><dd>'+clips.length+' clips on timeline</dd></div><div><dt>Output review</dt><dd>'+(approved?'Recorded':'Not yet accepted')+'</dd></div><div><dt>Source files</dt><dd>Kept on this machine</dd></div></dl><p class="slate-footnote">'+(approved?'Open the project for its reviewed output and source evidence.':'A saved plan or generated test is not a finished film.')+'</p></aside></section>'+workflowRail(featured)+'<div class="home-lower"><section class="home-projects"><div class="section-head"><h2>Continue working</h2><button class="text-action" data-nav="Catalog">Open catalog <span aria-hidden="true">↗</span></button></div>'+(ps.length?'<div class="grid project-grid">'+ps.slice(0,4).map(projectCard).join('')+'</div>':'<div class="empty"><strong>Your first project starts here</strong>Write a brief or import a saved project.</div>')+'</section><aside class="activity-panel"><div class="section-head"><h2>Production desk</h2><button class="text-action" data-nav="Jobs">All jobs ↗</button></div><div class="metrics"><div class="metric"><div class="metric-label">Active jobs</div><div class="metric-value">'+active+'</div><div class="metric-trend">current local queue</div></div><div class="metric"><div class="metric-label">Your projects</div><div class="metric-value">'+ps.length+'</div><div class="metric-trend">saved on this machine</div></div></div><div class="activity-list">'+(context.length?context.map(job=>'<div class="activity-item"><span class="status '+esc(job.status)+'">'+esc(job.status.replaceAll('_',' '))+'</span><strong>'+esc(job.type||'Production job')+'</strong><p>'+esc(job.stage||job.error||'Open Jobs for its saved details.')+'</p></div>').join(''):'<div class="activity-empty">Your next production steps will appear here.</div>')+'</div></aside></div>';
}
function preview(p,asset){const current=projectDisplayStatus(p);if(current.activeJob&&p.latestOutput?.status==='blocked')return `<div class="preview-empty"><strong>${esc(current.label)} · local production</strong><small>${esc(current.detail)}</small><small>${esc(previousBlockedDetail(p))}</small></div>`;if(p.latestOutput?.status==='blocked')return '<div class="preview-empty"><strong>Output blocked</strong><small>Review the job diagnostic before rendering again.</small></div>';const out=p.latestOutput?.videoAssetId&&store.state.assets.find(a=>a.id===p.latestOutput.videoAssetId);const src=out?.url||asset?.url; if(src && (out?.mime||asset?.mime||'').startsWith('video'))return `<video class="media-preview" controls preload="metadata" src="${esc(src)}"></video><a class="btn" data-job-id="${esc(p.latestOutput?.jobId||'')}" href="${esc(src)}" download="${esc((p.name||'vyrealm').replace(/[^a-z0-9-]+/gi,'-'))}.mp4">Download video</a>`; if(src && (out?.mime||asset?.mime||'').startsWith('image'))return `<img class="media-preview" src="${esc(src)}" alt="${esc(asset?.name||p.name)}">`; return `<div class="preview-empty"><span>◈</span><strong>${p.latestOutput?.status==='review_required'?'Visual review required':p.latestOutput?'No accepted preview':'Preview appears here'}</strong><small>${p.latestOutput?.status==='review_required'?'Technical checks passed; semantic visual review is still required.':p.latestOutput?'Open the rendered asset from this project.':'Import media or render a project to see playable output.'}</small></div>`; }
function cinema(){const p=store.project,clips=p?.timeline||[],settings=p?.settings||{};return `<div class="hero cinema-hero"><div><div class="eyebrow">Cinema / Director suite</div><h1>Direct the <em>sequence.</em></h1><p class="hero-copy">Turn a brief into a sequence of deliberate shots. Review pacing, coverage, and the editable scene before you render.</p></div>${p?`<div class="hero-actions"><span class="output-chip">${Number(settings.width||640)} × ${Number(settings.height||360)} · ${Number(settings.fps||24)} FPS</span><button class="btn" id="saveProject2">Save changes</button><button class="btn primary" id="directBtn">Run director <span>→</span></button></div>`:''}</div>${p?`<div class="director-overview"><div class="director-title"><div><div class="eyebrow">Current production</div><h2>${esc(p.name)}</h2></div><span class="revision-pill">REV ${p.revision||0}</span></div><p>${esc(p.brief||'No brief recorded.')}</p><div class="director-stats"><div><span>SHOTS</span><strong>${clips.length}</strong></div><div><span>RUNTIME</span><strong>${fmt(clips.reduce((n,c)=>n+Number(c.duration||0),0))}</strong></div><div><span>DELIVERY</span><strong>${Number(settings.fps||24)} FPS</strong></div><div><span>STATE</span><strong>${esc(projectDisplayStatus(p).label)}</strong></div></div></div><div class="storyboard-grid">${clips.length?clips.map((c,i)=>{const a=store.state.assets.find(x=>x.id===c.assetId);return `<button class="storyboard-card ${c.id===store.selectedClip?'selected':''}" data-clip="${esc(c.id)}"><div class="storyboard-number">${String(i+1).padStart(2,'0')}</div><div class="storyboard-art" ${a?.url&&a.kind==='image'?`style="background-image:url('${esc(a.url)}')"`:''}><span>${esc((a?.kind||'SHOT').toUpperCase())}</span></div><div class="storyboard-copy"><strong>${esc(a?.name||c.kind||'Untitled shot')}</strong><span>${fmt(c.duration)} · ${esc(c.caption||'No caption')}</span></div></button>`}).join(''):`<div class="empty"><strong>No shots yet</strong>Run the director or import footage from Create.</div>`}</div>`:`<div class="empty"><strong>Open a project first</strong>Choose a production from Explore.</div>`}`;}
function canvas(){const p=store.project,s=p?.scene||{objects:[],lights:[],camera:{}},o=s.objects?.[0],l=s.lights?.[0],pos=o?.position||[0,0,0];return `<div class="hero"><div><div class="eyebrow">Canvas / Production graph</div><h1>See every <em>layer.</em></h1><p class="hero-copy">Canvas reads the same scene document as Cinema. Transform edits stay attached to the project revision.</p></div>${p?`<div class="hero-actions"><button class="btn" id="saveProject2">Save revision</button><button class="btn primary" id="sceneBtn">Build / render scene</button></div>`:''}</div>${p?`<div class="workspace"><div class="panel"><div class="panel-title"><h3>Scene objects</h3><span class="eyebrow">${s.objects?.length||0} objects</span></div>${s.objects?.length?`<select id="sceneObject" class="scene-select">${s.objects.map(x=>`<option value="${esc(x.id)}">${esc(x.id)} · ${esc(x.type||'object')}</option>`).join('')}</select><div class="row"><div class="field"><label>POSITION X (M)</label><input type="number" step="0.01" data-scene="x" value="${Number(pos[0]||0)}"></div><div class="field"><label>POSITION Y (M)</label><input type="number" step="0.01" data-scene="y" value="${Number(pos[1]||0)}"></div></div><div class="field"><label>POSITION Z (M)</label><input type="number" step="0.01" data-scene="z" value="${Number(pos[2]||0)}"></div>`:`<div class="empty">No scene objects yet. Run Build / render scene.</div>`}<h3 class="subhead">Light</h3>${l?`<div class="field"><label>ENERGY</label><input type="number" min="0" step="1" data-scene-light value="${Number(l.energy||0)}"></div>`:`<div class="empty">No lights in this scene.</div>`}</div><div class="panel scene-summary"><div class="panel-title"><h3>Canonical scene</h3><span class="tag" style="position:static">EDITABLE</span></div><pre>${esc(JSON.stringify(s,null,2))}</pre></div></div>`:`<div class="empty"><strong>Open a project first</strong>Open a project to inspect its scene graph.</div>`}`;}
function library(){const assets=store.state.assets;return `<div class="hero"><div><div class="eyebrow">Library / Sources</div><h1>Your creative <em>memory.</em></h1><p class="hero-copy">Immutable source files and generated artifacts reported by the local control plane.</p></div><button class="btn primary" id="uploadBtn">＋ Import media</button></div><div class="panel asset-table">${assets.length?assets.map(a=>`<div class="asset-row"><span class="asset-kind">${esc(a.kind||'file')}</span><strong>${esc(a.name)}</strong><span>${esc(a.mime||'')} · ${fmtBytes(a.size)}</span><a href="${esc(a.url)}" target="_blank" rel="noreferrer">Open</a></div>`).join(''):`<div class="empty">No assets indexed yet.</div>`}</div>`;}
function jobControls(j){
 if(j.type==='ltx-qualification')return '<span class="micro">Controlled by the qualification runner</span>';
 return `${['queued','loading','running','validating','awaiting_review'].includes(j.status)?`<button class="btn small" data-job-cancel="${j.id}">Cancel</button>`:''}${['failed','cancelled'].includes(j.status)||j.status==='blocked'&&['generation-test','generation-shot'].includes(j.type)?`<button class="btn small" data-job-retry="${j.id}">Retry</button>`:''}`;
}
function jobs(){const jobs=store.state.jobs;return `<div class="hero"><div><div class="eyebrow">Jobs / Durable queue</div><h1>Nothing gets <em>lost.</em></h1><p class="hero-copy">Jobs survive a refresh and expose their actual stage, revision, and error. Retained shots can be inspected and applied after a project revision changes.</p></div></div><div class="panel job-table">${jobs.length?jobs.map(j=>`<div class="job-row"><div><strong>${esc(j.type)}</strong><span>${esc(j.projectId||'workspace')} · rev ${esc(j.revision||'—')}</span></div><span class="status ${esc(j.status)}">${esc(j.status)}${j.progress!=null?' · '+Math.round(j.progress*100)+'%':''}</span><span class="job-stage">${esc(j.stage||j.error||'')}</span>${jobControls(j)}${retainedShotAction(j)}</div>`).join(''):`<div class="empty">No jobs have been queued.</div>`}</div>`;}
function retainedShotAction(job){
 if(!['generation-test','generation-shot'].includes(job.type)||job.output?.promoted!==false||!job.output?.assets?.video||!['review_required','rejected','succeeded'].includes(job.status))return '';
 const project=store.state.projects.find(p=>p.id===job.projectId),applied=project?.operations?.some(op=>op.type==='apply_generated_shot'&&op.jobId===job.id);
 if(applied)return '<span class="meta">Retained shot applied</span>';
 return `<button class="btn small" data-retained-shot="${esc(job.id)}">${job.status==='succeeded'&&job.output.review?.verdict==='passed'?'Apply reviewed shot':'Review retained shot'}</button>`;
}
async function openRetainedShot(jobId){
 $('#retainedShotDialog')?.close();
 const dialog=document.createElement('dialog');dialog.id='retainedShotDialog';dialog.className='panel';dialog.setAttribute('aria-labelledby','retainedShotTitle');dialog.style.cssText='width:min(920px,calc(100vw - 32px));max-height:90vh;overflow:auto;color:var(--text);margin:auto;box-shadow:0 24px 100px #000b;';
 dialog.innerHTML='<div class="panel-title"><h3 id="retainedShotTitle">Retained generated shot</h3><button class="btn small" id="closeRetainedShot">Close</button></div><p role="status">Loading the saved job and its project…</p>';
 document.body.appendChild(dialog);dialog.addEventListener('close',()=>{dialog.querySelector('video')?.pause();dialog.remove();});dialog.querySelector('#closeRetainedShot').onclick=()=>dialog.close();dialog.showModal();
 try{const jobs=await api('/jobs'),job=jobs.find(j=>j.id===jobId);if(!job?.projectId)throw Error('The retained generated job is unavailable.');const project=await api(`/projects/${encodeURIComponent(job.projectId)}`);if(dialog.isConnected)renderRetainedShot(dialog,job,project);}
 catch(error){if(dialog.isConnected){const message=dialog.querySelector('[role="status"]');if(message){message.setAttribute('role','alert');message.textContent=error.message;}}}
}
function renderRetainedShot(dialog,job,project,{applied=false}={}){
 const output=job.output||{},assets=output.assets||{},passed=job.status==='succeeded'&&output.review?.verdict==='passed',provenance=output.provenance||{};
 const media=id=>`/media/${encodeURIComponent(id)}`;
 applied=applied||Boolean(project.operations?.some(op=>op.type==='apply_generated_shot'&&op.jobId===job.id));
 dialog.innerHTML=`<div class="panel-title"><div><h3 id="retainedShotTitle">Retained shot · ${esc(project.name||'Untitled project')}</h3><p class="meta">Job ${esc(job.id.slice(0,8))} · generated at revision ${esc(job.revision)} · current project revision ${esc(project.revision)}</p></div><button class="btn small" id="closeRetainedShot">Close</button></div><p>This completed shot was retained when the project changed. Inspect its movement, faces, hands and continuity before recording your decision.</p>${assets.video?`<video id="retainedShotVideo" class="media-preview" aria-label="Retained generated shot video" controls preload="metadata" src="${esc(media(assets.video))}" style="width:100%;max-height:45vh"></video><a class="btn small" href="${esc(media(assets.video))}" download>Download retained video</a>`:'<p role="alert">The saved job has no playable output asset.</p>'}${assets.poster?`<details><summary>Inspect contact sheet</summary><img alt="Retained shot contact sheet" src="${esc(media(assets.poster))}" style="max-width:100%;height:auto"></details>`:''}<p class="meta">${esc(provenance.providerId||'Provider unrecorded')} · ${esc(provenance.modelId||'Model unrecorded')} · ${esc(provenance.generationStatus||'Unrecorded source method')}</p><div class="field"><label for="retainedReviewNotes">REVIEW NOTES</label><textarea id="retainedReviewNotes" maxlength="4000" placeholder="Describe what you inspected and any visible defects.">${esc(output.review?.notes||'')}</textarea></div><div class="panel-actions"><button class="btn" data-retained-verdict="passed" ${!assets.video?'disabled':''}>Record passed review</button><button class="btn" data-retained-verdict="rejected" ${!assets.video?'disabled':''}>Reject retained shot</button></div><p id="retainedShotStatus" role="status" class="meta">${applied?'Applied to the saved project. Existing edits were retained.':passed?'Passed review recorded. This shot can now be applied to its project.':'Review is required. A playable file alone does not establish visual quality.'}</p><p class="meta">Apply attaches the reviewed assets and appends this five-second shot once. Existing timeline edits remain intact. It does not regenerate footage or replace the project.</p><button class="btn primary" id="applyRetainedShot" ${!passed||applied?'disabled':''}>${applied?'Applied to project':'Apply reviewed shot'}</button><p class="meta" style="overflow-wrap:anywhere">Output hash: ${esc(provenance.outputHash||'Unrecorded')}</p>`;
 dialog.querySelector('#closeRetainedShot').onclick=()=>dialog.close();
 const status=dialog.querySelector('#retainedShotStatus');
 dialog.querySelectorAll('[data-retained-verdict]').forEach(button=>button.onclick=async()=>{
   const notes=dialog.querySelector('#retainedReviewNotes').value.trim();if(!notes){status.textContent='Add notes from inspecting the actual clip before recording a review.';dialog.querySelector('#retainedReviewNotes').focus();return;}
   dialog.querySelectorAll('[data-retained-verdict],#applyRetainedShot').forEach(el=>el.disabled=true);
   try{await api('/generation/review',{method:'POST',body:JSON.stringify({jobId:job.id,verdict:button.dataset.retainedVerdict,notes,expectedOutputHash:reviewOutputHash(provenance)})});const jobs=await api('/jobs'),freshJob=jobs.find(j=>j.id===job.id),freshProject=await api(`/projects/${encodeURIComponent(job.projectId)}`);if(!freshJob)throw Error('The reviewed job is unavailable.');if(dialog.isConnected)renderRetainedShot(dialog,freshJob,freshProject);await refresh();toast('Retained shot review recorded');}
   catch(error){status.textContent=error.message;dialog.querySelectorAll('[data-retained-verdict]').forEach(el=>el.disabled=false);if(passed&&!applied)dialog.querySelector('#applyRetainedShot').disabled=false;}
 });
 dialog.querySelector('#applyRetainedShot').onclick=async e=>{
   const button=e.currentTarget;button.disabled=true;
   try{if(store.project?.id===job.projectId&&store.dirty&&!await saveProject())throw Error('Save the current project edits before applying this shot.');if(store.project?.id===job.projectId&&store.savePromise)await store.savePromise;const freshProject=await api(`/projects/${encodeURIComponent(job.projectId)}`);const result=await api('/generation/apply-retained',{method:'POST',body:JSON.stringify({projectId:job.projectId,jobId:job.id,expectedRevision:freshProject.revision})});if(store.project?.id===job.projectId&&!store.dirty)store.project=result.project;if(dialog.isConnected)renderRetainedShot(dialog,job,result.project,{applied:true});await refresh();toast(result.alreadyApplied?'Shot was already applied; no duplicate added':'Reviewed shot applied; existing edits retained');}
   catch(error){status.textContent=error.message;if(button.isConnected)button.disabled=false;}
 };
}
