async function queueJob(type){
  if(!store.project){fail('Create or open a project first.');return;}
  try{
    if(store.dirty){const saved=await saveProject();if(!saved)return;}
    const body={projectId:store.project.id,type,expectedRevision:store.project.revision};
    const generate=type==='produce'&&store.project.mode==='cinematic'&&!store.project.sampleId&&!store.project.timeline?.length;
    if(generate)return await startGenerationTest(true);
    const job=await api('/jobs',{method:'POST',body:JSON.stringify(body)});
    toast(`${type} job queued`);store.active='Jobs';await refresh();render();
    return job;
  }catch(e){fail(`Could not queue ${type}: ${e.message}`);}
}
